package ch.jalu.configme.configurationdata;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.lang.reflect.Method;

public class CommentsConfigurationTest {

    @Test
    public void constructorShouldInitializeMap() {
        CommentsConfiguration comments = new CommentsConfiguration();
        assertNull(comments.comments);
    }

    @Test
    public void constructorWithCommentsShouldInitializeComments() throws Exception {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path1", Arrays.asList("line1"));
        comments.put("path2", Arrays.asList("line2"));
        CommentsConfiguration commentsConfig = new CommentsConfiguration(comments);
        assertEquals(comments, commentsConfig.comments);
    }

    @Test
    public void setCommentShouldAddNewComment() {
        CommentsConfiguration comments = new CommentsConfiguration();
        String comment = "new line";
        comments.setComment("path1", comment);
        assertTrue(comments.comments.containsKey("path1"));
        assertEquals(Arrays.asList(comment), comments.comments.get("path1"));
    }

    @Test
    public void setCommentShouldReplaceExistingComments() {
        CommentsConfiguration comments = new CommentsConfiguration();
        String comment = "new line";
        comments.setComment("path1", comment);
        String otherComment = "other line";
        comments.setComment("path1", otherComment);
        assertEquals(Arrays.asList(otherComment), comments.comments.get("path1"));
    }

    @Test
    public void setCommentShouldNotAddEmptyLines() {
        CommentsConfiguration comments = new CommentsConfiguration();
        String[] lines = {"line 1\n", "line2"};
        comments.setComment("path1", lines);
        assertTrue(comments.comments.containsKey("path1"));
        assertEquals(Arrays.asList(lines), comments.comments.get("path1"));
    }

    @Test
    public void getAllCommentsShouldReturnUnmodifiableMap() {
        CommentsConfiguration comments = new CommentsConfiguration();
        Map<String, List<String>> map = Collections.unmodifiableMap(comments.comments);
        assertTrue(map instanceof java.util.Map);
        assertTrue(((java.util.Map) map).containsKey("path1"));
        assertEquals(1, ((java.util.Map) map).size());
    }

    @Test
    public void getAllCommentsShouldReturnCommentLinesAsUnmodifiableList() {
        CommentsConfiguration comments = new CommentsConfiguration();
        comments.setComment("path1", Arrays.asList("line1", "line2"));
        Map<String, List<String>> map = comments.getAllComments();
        assertTrue(map.containsKey("path1"));
        assertEquals(2, ((java.util.List) map.get("path1")).size());
    }

    @Test
    public void testSetCommentMultipleLines() {
        CommentsConfiguration comments = new CommentsConfiguration();
        String comment = "new line 1\nnew line 2";
        comments.setComment("path1", comment.split("\n"));
        assertTrue(comments.comments.containsKey("path1"));
        assertEquals(Arrays.asList(comment.split("\n")), comments.comments.get("path1"));
    }
}
